'use client'

import { useRef, useEffect, useState } from 'react'
import { Canvas, useFrame } from '@react-three/fiber'
import { OrbitControls } from '@react-three/drei'
import * as THREE from 'three'

// Extend JSX to include React Three Fiber elements
import type { ThreeElements } from '@react-three/fiber'
declare module 'react' {
  namespace JSX {
    interface IntrinsicElements extends ThreeElements {}
  }
}

function Asteroid() {
  const meshRef = useRef<THREE.Mesh>(null!)
  
  // Rotate asteroid and orbit around sun
  useFrame((state) => {
    const time = state.clock.getElapsedTime()
    if (meshRef.current) {
      // Rotate on its own axis
      meshRef.current.rotation.y += 0.02
      meshRef.current.rotation.x += 0.01
      
      // Orbit around sun
      const radius = 4
      meshRef.current.position.x = Math.cos(time * 0.5) * radius
      meshRef.current.position.z = Math.sin(time * 0.5) * radius
    }
  })

  return (
    <mesh ref={meshRef} position={[4, 0, 0]}>
      <sphereGeometry args={[0.3, 16, 16]} />
      <meshStandardMaterial color="#888888" roughness={0.8} />
    </mesh>
  )
}

function OrbitRing() {
  const points = []
  const radius = 4
  const segments = 64
  
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * Math.PI * 2
    points.push(
      new THREE.Vector3(
        Math.cos(theta) * radius,
        0,
        Math.sin(theta) * radius
      )
    )
  }
  
  const lineGeometry = new THREE.BufferGeometry().setFromPoints(points)
  
  return (
    <primitive object={new THREE.Line(
      lineGeometry,
      new THREE.LineBasicMaterial({ color: '#444444', opacity: 0.5, transparent: true })
    )} />
  )
}

function Sun() {
  const meshRef = useRef<THREE.Mesh>(null!)
  
  useFrame(() => {
    if (meshRef.current) {
      meshRef.current.rotation.y += 0.005
    }
  })
  
  return (
    <mesh ref={meshRef}>
      <sphereGeometry args={[1.2, 32, 32]} />
      <meshStandardMaterial 
        color="#ff6b00" 
        emissive="#ff6b00" 
        emissiveIntensity={0.5}
      />
    </mesh>
  )
}

function Scene() {
  return (
    <>
      {/* Lighting */}
      <ambientLight intensity={0.3} />
      <pointLight position={[0, 0, 0]} intensity={2} color="#ffaa00" />
      
      {/* Solar System Objects */}
      <Sun />
      <OrbitRing />
      <Asteroid />
      
      {/* Camera Controls */}
      <OrbitControls 
        enableZoom={true}
        enablePan={true}
        minDistance={3}
        maxDistance={15}
      />
    </>
  )
}

export default function SolarSystem() {
  const [isClient, setIsClient] = useState(false)

  useEffect(() => {
    setIsClient(true)
  }, [])

  if (!isClient) {
    return (
      <div className="w-full h-[400px] bg-black/20 rounded-lg overflow-hidden border border-border flex items-center justify-center">
        <p className="text-slate-400 text-sm">Loading 3D visualization...</p>
      </div>
    )
  }

  return (
    <div className="w-full h-[400px] bg-black/20 rounded-lg overflow-hidden border border-border">
      <Canvas
        camera={{ position: [0, 5, 8], fov: 50 }}
        gl={{ antialias: true, alpha: true }}
      >
        <Scene />
      </Canvas>
    </div>
  )
}
